using System.Globalization;

namespace Tellma.Core.Abstractions.Caching
{
    /// <summary>
    ///     An opaque marker of one state of something the platform caches: the tenant's settings, its
    ///     permissions, a reference list. Every batch that writes a tagged table stamps one fresh tag,
    ///     generated by the application, on every name it bumps; a cache entry is current exactly when
    ///     it carries the tag the database holds.
    /// </summary>
    /// <remarks>
    ///     Tags are compared for equality only: they are never ordered, never indexed, never
    ///     arithmetic. <see cref="None" /> stands for a tag never read; it matches no entry, so a
    ///     comparison against it always loads.
    /// </remarks>
    /// <param name="Value">The tag's value, a <c>uniqueidentifier</c> in the database.</param>
    public sealed record VersionTag(Guid Value)
    {
        /// <summary>The empty tag: never read, so it matches no cache entry.</summary>
        public static VersionTag None { get; } = new(Guid.Empty);

        /// <summary>A fresh tag, generated by the application for one batch.</summary>
        /// <returns>The tag.</returns>
        public static VersionTag New()
        {
            return new VersionTag(Guid.NewGuid());
        }

        /// <summary>
        ///     The tag as a client sees it: <c>{formatVersion}.{value}</c>, the value as 32 lower-case
        ///     hexadecimal digits. A client stores a shape keyed by this string and fetches it again
        ///     when the string changes, whether the data moved or the shape's format version did.
        /// </summary>
        /// <param name="formatVersion">The format version of the client-facing shape the tag covers, at least 1.</param>
        /// <returns>The wire form, for example <c>1.3f2504e04f8941d39a0c0305e82c3301</c>.</returns>
        /// <exception cref="ArgumentOutOfRangeException"><paramref name="formatVersion" /> is less than 1.</exception>
        public string ToWire(int formatVersion)
        {
            ArgumentOutOfRangeException.ThrowIfLessThan(formatVersion, 1);
            return string.Create(CultureInfo.InvariantCulture, $"{formatVersion}.{Value:N}");
        }
    }
}
